diff --git a/docs/install.md b/docs/install.md
index cbc59ab..d1f05bc 100644
--- a/docs/install.md
+++ b/docs/install.md
@@ -1,3 +1,21 @@
 # Installing

-Run `npx toolkit`. See `package.json` for the supported runtime range.
+Run `npx toolkit`.
+
+## Requirements
+
+Node.js 22 or later is required. This ensures all dependencies receive active security updates.
+
+### Checking your Node.js version
+
+```sh
+node --version
+```
+
+If you see an older version, upgrade:
+
+- **With nvm:** `nvm install 22 && nvm use 22`
+- **macOS with Homebrew:** `brew install node@22`
+- **Direct:** Visit https://nodejs.org/
+
+After upgrading, verify with `node --version` again, then retry `npx toolkit`.
diff --git a/scripts/check-engines.mjs b/scripts/check-engines.mjs
index ce51156..1d5267c 100644
--- a/scripts/check-engines.mjs
+++ b/scripts/check-engines.mjs
@@ -2,9 +2,20 @@ import { readFileSync } from "node:fs";

 const pkg = JSON.parse(readFileSync("package.json", "utf8"));
 const declared = pkg.engines?.node ?? "";
+const current = process.version.slice(1);
 const floor = Number(declared.replace(/[^0-9]/g, "").slice(0, 2));

 if (!Number.isInteger(floor) || floor < 22) {
   console.error(`engines.node is "${declared}" — the floor may not go below 22`);
   process.exit(1);
 }
+
+if (Number(current.split(".")[0]) < floor) {
+  console.error(`\nNode.js ${current} is installed, but ${pkg.name} requires >= ${floor}.0`);
+  console.error(`\nWhy: direct dependencies need active security support.`);
+  console.error(`Node ${floor} is supported until late 2027.\n`);
+  console.error(`To upgrade:`);
+  console.error(`  • With nvm: nvm install ${floor} && nvm use ${floor}`);
+  console.error(`  • Or visit: https://nodejs.org/\n`);
+  process.exit(1);
+}
